def generate(rng):
    # Rectangular lattice of 2x2 rooms separated by color-6 walls.
    nr = rng.randint(3, 6)
    nc = rng.randint(3, 6)
    h, w = 3*nr-1, 3*nc-1
    g = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r%3==2 or c%3==2: g[r][c]=6
    # place a few 2x2 colored objects, mostly color 1, with occasional 5 marker
    rooms=[(r,c) for r in range(nr) for c in range(nc)]
    rng.shuffle(rooms)
    for r,c in rooms[:rng.randint(2, min(len(rooms),6))]:
        col = 5 if rng.random()<0.25 else 1
        for dr in (0,1):
            for dc in (0,1): g[3*r+dr][3*c+dc]=col
    return g"}

